#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

banner "LineLock on AMD and Evolus"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "AMD Developer Cloud credits"
say "Complimentary GPU hours are applied for, then deposited. AMD's cloud page says that takes three business days after approval."
open_url "https://www.amd.com/en/developer/resources/cloud-access/amd-developer-cloud.html"
step "Sign in with the AMD AI Developer Program account. Request complimentary hours if the balance is empty."
note "There is no GPU on this laptop, and no AMD credential in the environment. This wizard cannot create the droplet."
pause "Press Enter when the console shows a credit balance, or when you already know you can create a droplet."

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Create one MI300X droplet"
open_url "https://devcloud.amd.com"
step "Create a GPU droplet. Choose a single MI300X."
step "If the image list has a vLLM Quick Start image, choose that. If it does not, choose the ROCm Software image. Both appear in published guides; the console is what lists images today."
step "Add your SSH key. Create the droplet. Copy the public IP from the overview page."
ask DROPLET_IP "Paste the droplet public IP:"
write_env DROPLET_IP "$DROPLET_IP"

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Serve Qwen2.5-7B-Instruct"
say "SSH in with: ssh root@${DROPLET_IP}"
say "If you chose the vLLM Quick Start image, the published guide enters the container with: docker exec -it rocm /bin/bash"
say "Copy scripts/serve-qwen-on-amd.sh onto the droplet and run it with an API key you invent. Leave that process running."
note "The script is: vllm serve Qwen/Qwen2.5-7B-Instruct --host 0.0.0.0 --port 8000 --api-key <key> --enable-auto-tool-choice --tool-call-parser hermes"
note "Evolus documents that hermes parser for Qwen, port 8000, and --api-key. https://evolus.ai/en/developers"
ask_secret LLM_API_KEY "Paste the API key you passed to vllm serve:"
pause "Press Enter once vllm serve is up. The next step curls the droplet from this laptop."
if curl -fsS -m 20 -H "Authorization: Bearer ${LLM_API_KEY}" "http://${DROPLET_IP}:8000/v1/models"; then
  printf '\n'
  note "The droplet answered /v1/models."
else
  printf '\n'
  warn "The laptop could not reach port 8000. The published pages do not name the firewall control. Open TCP 8000 for this droplet in the cloud console, then re-run this wizard."
fi
write_env LLM_BASE_URL "http://${DROPLET_IP}:8000/v1"
write_env LLM_API_KEY "$LLM_API_KEY"
write_env LLM_MODEL "Qwen/Qwen2.5-7B-Instruct"

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Evolus event workspace"
say "A workspace created outside the event link is not an event workspace."
open_url "https://app.evolus.ai/join/AMDACT3"
step "Sign in with GitHub, Google, Apple, or Microsoft. The coupon AMDACT3 is already in that link. Create the team workspace from this page."
step "On the workspace API keys page, create an API key. The same page shows the space id. That id is X-Application-Id."
ask_secret EVOLUS_API_KEY "Paste the Evolus API key:"
ask EVOLUS_APPLICATION_ID "Paste the space id:"
write_env EVOLUS_BASE_URL "https://api.evolus.ai"
write_env EVOLUS_API_KEY "$EVOLUS_API_KEY"
write_env EVOLUS_APPLICATION_ID "$EVOLUS_APPLICATION_ID"

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Connect the droplet model in Evolus"
say "In the workspace, add an OpenAI-compatible model, test it, and pick it on the agent."
step "Base URL: http://${DROPLET_IP}:8000/v1"
step "Model: Qwen/Qwen2.5-7B-Instruct"
step "API key: the same value you passed to vllm serve."
note "The developer page says calls to your model do not spend Evolus credits. It does not name the menu beyond adding the model and testing the connection."
pause "Press Enter after the connection test in the workspace succeeds."

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "Workflow id"
say "Create a workflow that takes a text input, then turn it on. An off workflow returns 409."
note "The developer page publishes POST /api/v1/workflows/{workflowId}/execute. It does not name the screen that shows the id. Copy the id from the workflow URL or the in-app API reference."
ask EVOLUS_WORKFLOW_ID "Paste the workflow id:"
write_env EVOLUS_WORKFLOW_ID "$EVOLUS_WORKFLOW_ID"

# ── Stage 7 ────────────────────────────────────────────────────────────────
stage "Translation tool and library"
say "Translation uses POST /api/v1/ai-tools/translate/run. That spends platform credits. The tool name is fixed; there is no id to copy."
if confirm "Use the Evolus translate tool for supplier emails?"; then
  write_env TRANSLATE_BACKEND "evolus"
else
  write_env TRANSLATE_BACKEND "local"
fi
say "Create a library in the workspace. Indexing uses credits. The gateway still checks quotes against data/library on disk."
note "The upload path is POST /api/v1/memories/{libraryId}/documents?language=en. The page does not name the menu that shows the library id."
ask EVOLUS_LIBRARY_ID "Paste the library id, or leave blank to skip the upload:"
if [[ -n "${EVOLUS_LIBRARY_ID}" ]]; then
  write_env EVOLUS_LIBRARY_ID "$EVOLUS_LIBRARY_ID"
  root="$(cd "$(dirname "$0")/.." && pwd)"
  for file in "$root"/data/library/*.md; do
    step "Uploading $(basename "$file")"
    curl -fsS -X POST "https://api.evolus.ai/api/v1/memories/${EVOLUS_LIBRARY_ID}/documents?language=en" \
      -H "X-ApiKey: ${EVOLUS_API_KEY}" \
      -H "X-Application-Id: ${EVOLUS_APPLICATION_ID}" \
      -F "file=@${file}" >/dev/null
  done
  note "Uploads returned. Indexing finishes in the background."
fi
say "An extractor is optional. The published path is POST /api/v1/agents/{agentId}/json/{extractorId}/ask-file."
note "Leave these blank to keep reading the packet PDFs locally. The workspace schema has to return an object with a fields map."
ask EVOLUS_AGENT_ID "Paste the agent id, or leave blank:"
ask EVOLUS_EXTRACTOR_ID "Paste the extractor id, or leave blank:"
if [[ -n "${EVOLUS_AGENT_ID}" && -n "${EVOLUS_EXTRACTOR_ID}" ]]; then
  write_env EVOLUS_AGENT_ID "$EVOLUS_AGENT_ID"
  write_env EVOLUS_EXTRACTOR_ID "$EVOLUS_EXTRACTOR_ID"
  write_env EXTRACTOR "evolus"
else
  write_env EXTRACTOR "local"
fi

# ── Stage 8 ────────────────────────────────────────────────────────────────
stage "A gateway URL that outlasts the free tunnel"
say "The Vercel page currently proxies to a free Pinggy tunnel on this laptop. That link expires about an hour after it starts."
say "The durable host is the droplet. Copy this repo there, install Python 3.13, and run the gateway on 0.0.0.0:8080 with the .env from this wizard and LLM_BASE_URL=http://127.0.0.1:8000/v1."
say "Open TCP 8080 the same way you opened 8000. Then the public gateway is http://${DROPLET_IP}:8080"
note "From linelock/: python eval/run.py   That replaces docs/eval.md only after it finishes. Do not copy the stand-in 12/12 into that file."
ask GATEWAY_URL "Paste the public gateway URL (http://${DROPLET_IP}:8080 once it answers):"
write_env GATEWAY_URL "$GATEWAY_URL"
if confirm "Point https://linelock-amber.vercel.app at that URL and redeploy now?"; then
  root="$(cd "$(dirname "$0")/.." && pwd)"
  "$root/scripts/point-vercel-gateway.sh" "$GATEWAY_URL"
fi

finish
